For `parse_color`, regex ensures correct format, converting hex to RGB. For `format_color`, validate input and check for short-form eligibility by comparing hex digits.

```python
import re

def parse_color(text):
    if not isinstance(text, str):
        raise ValueError
    match = re.fullmatch(r'#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})', text)
    if not match:
        raise ValueError
    hex_part = match.group(1)
    if len(hex_part) == 3:
        hex_part = ''.join([c * 2 for c in hex_part])
    r = int(hex_part[0:2], 16)
    g = int(hex_part[2:4], 16)
    b = int(hex_part[4:6], 16)
    return (r, g, b)

def format_color(rgb):
    if not isinstance(rgb, (tuple, list)) or len(rgb) != 3:
        raise ValueError
    for val in rgb:
        if not isinstance(val, int) or val < 0 or val > 255 or isinstance(val, bool):
            raise ValueError
    r, g, b = rgb
    def to_hex(v):
        h = hex(v)[2:]
        return h if len(h) == 2 else '0' + h
    hr, hg, hb = to_hex(r), to_hex(g), to_hex(b)
    if all(c[0] == c[1] for c in [hr, hg, hb]):
        return '#' + hr[0] + hg[0] + hb[0]
    return '#' + hr + hg + hb
```

