def cents_to_text(cents):
    if not isinstance(cents, int) or isinstance(cents, bool):
        raise ValueError("Input must be an integer.")
    negative = cents < 0
    cents = abs(cents)
    dollars = cents // 100
    cents_part = cents % 100
    # Format dollars with commas
    if dollars == 0:
        dollars_str = "0"
    else:
        # Convert to string and add commas
        s = str(dollars)
        reversed_s = s[::-1]
        chunks = []
        for i in range(0, len(reversed_s), 3):
            chunk = reversed_s[i:i+3][::-1]
            # Reverse the chunk to maintain original order
            chunks.append(chunk)
        chunks.reverse()  # Reverse the list to get original order
        dollars_str = ",".join(chunks)
    # Format cents part with leading zero if needed
    cents_str = f"{cents_part:02d}"
    if negative:
        return f"-{dollars_str}.{cents_str}"
    else:
        return f"{dollars_str}.{cents_str}"

def text_to_cents(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string.")
    # Check if text is valid
    original_text = text
    sign = 1
    if text.startswith('-'):
        sign = -1
        text = text[1:]
    else:
        text = text
    # Split into dollars and cents
    parts = text.split('.')
    if len(parts) != 2:
        raise ValueError("Invalid format.")
    dollars_str, cents_str = parts
    # Validate cents part
    if len(cents_str) != 2 or not cents_str.isdigit():
        raise ValueError("Invalid cents part.")
    cents_value = int(cents_str)
    # Validate dollars part
    if not dollars_str:
        if sign == 1:
            dollars_value = 0
        else:
            raise ValueError("Invalid format.")
    else:
        # Check for leading zeros
        if len(dollars_str) > 1 and dollars_str[0] == '0':
            raise ValueError("Invalid leading zeros.")
        # Remove commas and validate commas placement
        clean_dollars = dollars_str.replace(',', '')
        if not clean_dollars.isdigit():
            raise ValueError("Invalid dollars part.")
        # Check commas placement
        dollars_groups = dollars_str.split(',')
        if len(dollars_groups) == 1:
            # No commas, valid if it's a single number
            pass
        else:
            # First group can be 1-3 digits, others must be 3
            if len(dollars_groups[0]) == 0:
                raise ValueError("Invalid format.")
            for i in range(1, len(dollars_groups)):
                if len(dollars_groups[i]) != 3:
                    raise ValueError("Invalid commas placement.")
    dollars_value = int(dollars_str.replace(',', ''))
    total_cents = dollars_value * 100 + cents_value
    total_cents *= sign
    # Special cases to reject
    if total_cents == 0 and original_text != "0.00":
        raise ValueError("Invalid zero representation.")
    return total_cents
