To implement the `cidr_range(text)` function, we first validate the input string to ensure it strictly adheres to the CIDR notation format. We then parse and convert the IPv4 address and prefix into a 32-bit integer for bitwise manipulation to compute the first and last addresses. Finally, we convert the resulting integers back to dotted-decimal strings and calculate the size of the CIDR block using the power of two based on the prefix length.

---

```python
def cidr_range(text):
    if not isinstance(text, str):
        raise ValueError

    parts = text.split('/')
    if len(parts) != 2:
        raise ValueError

    ip_part, prefix_part = parts

    if ip_part.count('.') != 3:
        raise ValueError

    ip_octets = ip_part.split('.')
    if len(ip_octets) != 4:
        raise ValueError

    for octet in ip_octets:
        if not octet.isdigit():
            raise ValueError
        if len(octet) > 1 and octet[0] == '0':
            raise ValueError
        num = int(octet)
        if not (0 <= num <= 255):
            raise ValueError

    if not prefix_part.isdigit():
        raise ValueError
    if len(prefix_part) > 1 and prefix_part[0] == '0':
        raise ValueError
    prefix = int(prefix_part)
    if not (0 <= prefix <= 32):
        raise ValueError

    ip_int = 0
    for octet in ip_octets:
        ip_int = (ip_int << 8) | int(octet)

    mask_length = 32 - prefix
    first = (ip_int >> mask_length) << mask_length
    last = first | ((1 << mask_length) - 1)
    size = 1 << mask_length

    def int_to_ip(n):
        return f"{(n >> 24) & 0xFF}.{(n >> 16) & 0xFF}.{(n >> 8) & 0xFF}.{n & 0xFF}"

    return (int_to_ip(first), int_to_ip(last), size)
```

