import re

def to_24h(text):
    match = re.fullmatch(r'([1-9]|1[0-2]):([0-5][0-9]) (AM|PM)', text)
    if not match:
        raise ValueError
    h_12, m, period = match.groups()
    h_12 = int(h_12)
    m = int(m)
    if period == 'AM':
        hh = 0 if h_12 == 12 else h_12
    else:
        hh = 12 if h_12 == 12 else h_12 + 12
    return f"{hh:02}:{m:02d}"

def to_12h(text):
    match = re.fullmatch(r'([0-1][0-9]|2[0-3])(:([0-5][0-9]))', text)
    if not match:
        raise ValueError
    hour_str, _, m_str = match.groups()
    h_24 = int(hour_str)
    m = int(m_str)
    if h_24 == 0:
        return f"12:{m:02d} AM"
    elif 1 <= h_24 < 12:
        return f"{h_24}:{m:02d} AM"
    elif h_24 == 12:
        return f"12:{m:02d} PM"
    else:
        h_12 = h_24 - 12
        return f"{h_12}:{m:02d} PM"
