def luhn_valid(number):
    if not isinstance(number, str) or len(number) < 2:
        raise ValueError("Input must be a string of at least two digits")
    if not number.isdigit():
        raise ValueError("Input must contain only digits")
    total = 0
    for i, ch in enumerate(reversed(number)):
        digit = int(ch)
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0

def luhn_append(partial):
    if not isinstance(partial, str) or len(partial) < 1:
        raise ValueError("Input must be a string of at least one digit")
    if not partial.isdigit():
        raise ValueError("Input must contain only digits")
    # Calculate what check digit would need to be
    total = 0
    for i, ch in enumerate(reversed(partial + '0')):  # Add placeholder '0' for calculation
        digit = int(ch)
        if i % 2 == 1:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    # The check digit is (10 - (total % 10)) % 10
    check_digit = (10 - (total % 10)) % 10
    return partial + str(check_digit)
