        key_str, val_str = part.split("=", 1)
        if not key_str:
            raise ValueError("Key cannot be empty.")
        key = decode(key_str)
        val = decode(val_str)
        pairs.append((key, val))
    return pairs

def decode(s):
    s = s.replace("+", " ")
    i = 0
    result = []
    while i < len(s):
        if s[i] == "%":
            if i + 2 > len(s):
                raise ValueError("Incomplete % escape.")
            hex_part = s[i + 1:i + 3].lower()
            try:
                code = int(hex_part, 16)
            except ValueError:
                raise ValueError("Invalid hex in % escape.")
            if code > 0x7F:
                raise ValueError("Escape code above 7F.")
            result.append(chr(code))
            i += 3
        else:
            result.append(s[i])
            i += 1
    return "".join(result)

def build_query(pairs):
    if not isinstance(pairs, (list, tuple)):
        raise ValueError("Pairs must be a list or tuple.")
    encoded_parts = []
    for key, val in pairs:
        if not isinstance(key, str) or not isinstance(val, str):
            raise ValueError("Key and value must be strings.")
        if not key:
            raise ValueError("Key cannot be empty.")
        for s in (key, val):
            if any(ord(c) >= 128 for c in s):
                raise ValueError("Non-ASCII character in key or value.")
        encoded_key = encode(key)
        encoded_val = encode(val)
        encoded_parts.append(f"{encoded_key}={encoded_val}")
    return "&".join(encoded_parts)

def encode(s):
    result = []
    for c in s:
        if c in "-._~" or c.isalnum():
            result.append(c)
        elif c == " ":
            result.append("+")
        else:
            result.append(f"%{ord(c):02X}")
    return "".join(result)

