def triangle_kind(a, b, c):
    def validate_point(p):
        if not (isinstance(p, (list, tuple)) and len(p) == 2):
            raise ValueError
        for coord in p:
            if not (isinstance(coord, int) and not isinstance(coord, bool)):
                raise ValueError

    validate_point(a)
    validate_point(b)
    validate_point(c)

    # Check if degenerate
    ax, ay = a
    bx, by = b
    cx, cy = c
    cross = (bx - ax) * (cy - ay) - (cx - ax) * (by - ay)
    if cross == 0:
        return "degenerate"

    # Compute squared side lengths
    def sq_dist(p1, p2):
        dx = p1[0] - p2[0]
        dy = p1[1] - p2[1]
        return dx * dx + dy * dy

    s_ab = sq_dist(a, b)
    s_bc = sq_dist(b, c)
    s_ac = sq_dist(a, c)

    # Determine sides
    if s_ab == s_bc or s_ab == s_ac or s_bc == s_ac:
        sides = "isosceles"
    else:
        sides = "scalene"

    # Determine angle
    s = sorted([s_ab, s_bc, s_ac])
    s1, s2, s3 = s
    if s3 == s1 + s2:
        angle = "right"
    elif s3 > s1 + s2:
