def tree_centers(n, edges):
    if not isinstance(n, int) or n < 1 or n > 100000:
        raise ValueError("Invalid n")
    if not (isinstance(edges, (list, tuple)) and len(edges) == n - 1):
        raise ValueError("Invalid edges length")
    for i, edge in enumerate(edges):
        if not (isinstance(edge, (tuple, list)) and len(edge) == 2):
            raise ValueError(f"Edge {i} invalid")
        u, v = edge
        if not (isinstance(u, int) and isinstance(v, int)):
            raise ValueError(f"Edge {i} has non-int")
        if isinstance(u, bool) or isinstance(v, bool):
            raise ValueError(f"Edge {i} has bool")
        if not (0 <= u < n and 0 <= v < n):
            raise ValueError(f"Edge {i} out of bounds")

    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    def bfs(start):
        max_dist = 0
        farthest_node = start
        parent = {}
        dist = [ -1 ] * n
        q = deque()
        q.append(start)
        dist[start] = 0
        while q:
            node = q.popleft()
            for neighbor in adj[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    q.append(neighbor)
                    if dist[neighbor] > max_dist:
                        max_dist = dist[neighbor]
                        farthest_node = neighbor
        return farthest_node, parent, max_dist

    u, _, _ = bfs(0)
    v, parent, diameter = bfs(u)

    # Reconstruct the path from u to v
    path = []
    current = v
    while current != u:
        path.append(current)
        current = parent[current]
    path.append(u)
    path.reverse()

    # Determine centers
    if diameter % 2 == 0:
        mid = diameter // 2
        center1 = path[mid]
        centers = [center1]
    else:
        mid1 = diameter // 2 - 1
        mid2 = diameter // 2
        center1 = path[mid1]
        center2 = path[mid2]
        centers = [center1, center2]

    radius = (diameter + 1) // 2
    return (sorted(centers), radius)

