                L[i][j] = 1 + L[i + 1][j + 1]
            else:
                L[i][j] = max(L[i + 1][j], L[i][j + 1])

    i, j = 0, 0
    res = []

    while i < m and j < n and L[i][j] > 0:
        current_len = L[i][j]
        candidates = set()
        for k in range(i, m):
            if a[k] in set(b[j:]):
                candidates.add(a[k])
        for c in sorted(candidates):
            x = a.find(c, i)
            y = b.find(c, j)
            if x != -1 and y != -1 and L[x + 1][y + 1] == current_len - 1:
                res.append(c)
                i, j = x + 1, y + 1
                break

    return ''.join(res)

