def chain_order(dims):
    if not isinstance(dims, (list, tuple)):
        raise ValueError
    n = len(dims)
    if not (2 <= n <= 27):
        raise ValueError
    for d in dims:
        if isinstance(d, bool):
            raise ValueError
        if not isinstance(d, int):
            raise ValueError
        if not (1 <= d <= 1000):
            raise ValueError

    m = len(dims) - 1
    cost = [[0] * m for _ in range(m)]
    split = [[0] * m for _ in range(m)]

    for l in range(2, m + 1):  # l is the number of matrices in the chain
        for i in range(m - l + 1):
            j = i + l - 1
            cost[i][j] = float('inf')
            for k in range(i, j):
                temp = cost[i][k] + cost[k + 1][j] + dims[i] * dims[k + 1] * dims[j + 1]
                if temp < cost[i][j]:
                    cost[i][j] = temp
                    split[i][j] = k

    def build_order(i, j):
        if i == j:
            return chr(ord('A') + i)
        k = split[i][j]
        left = build_order(i, k)
        right = build_order(k + 1, j)
        return f"({left}{right})"

    if m == 1:
        return (0, "A")
    return (cost[0][m - 1], build_order(0, m - 1))
