To implement the Luhn check, process digits from right to left, doubling every second digit. Sum all digits, adding the doubled digits as modified if over 9. The sum must be a multiple of 10 for validity. For `luhn_valid`, validate the string meets criteria and apply the algorithm. For `luhn_append`, compute the check digit that makes the sum valid.

```python
def luhn_valid(number):
    if not isinstance(number, str) or len(number) < 2:
        raise ValueError
    if not number.isdigit():
        raise ValueError
    total = 0
    for i, c in enumerate(reversed(number)):
        digit = int(c)
        if i % 2 == 1:
            doubled = digit * 2
            if doubled > 9:
                doubled -= 9
            total += doubled
        else:
            total += digit
    return total % 10 == 0

def luhn_append(partial):
    if not isinstance(partial, str) or len(partial) < 1:
        raise ValueError
    if not partial.isdigit():
        raise ValueError
    total = 0
    for i, c in enumerate(reversed(partial)):
        digit = int(c)
        if i % 2 == 0:  # Because in append, we add a new digit to the right, which becomes the first in reversed
            total += digit
        else:
            doubled = digit * 2
            if doubled > 9:
                doubled -= 9
            total += doubled
    # The new digit is at position 0 in the reversed string, so it's added as is
    # We need to find the check digit such that (total + check) %10 ==0
    # So check = (10 - (total %10)) %10
    check = (10 - (total % 10)) % 10
    return partial + str(check)
