def sieve_eratosthenes(n):
    """Generate a sieve of Eratosthenes up to n."""
    if n < 2:
        return []
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            sieve[i*i : n+1 : i] = [False] * len(sieve[i*i : n+1 : i])
    return sieve

def goldbach_pairs(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 4 or n > 1000000 or n % 2 != 0:
        raise ValueError
    sieve = sieve_eratosthenes(n)
    count = 0
    for p in range(2, n // 2 + 1):
        if sieve[p]:
            q = n - p
            if sieve[q]:
                count += 1
    return count

def goldbach_smallest(n):
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError
    if n < 4 or n > 1000000 or n % 2 != 0:
        raise ValueError
    sieve = sieve_eratosthenes(n)
    for p in range(2, n // 2 + 1):
        if sieve[p]:
            q = n - p
            if sieve[q]:
                return (p, q)
    return None  # This line is theoretically unreachable as per the problem statement
```

