        raise ValueError("Grid is empty")
    row_length = len(grid[0])
    for row in grid:
        if len(row) != row_length or not isinstance(row, str):
            raise ValueError("Invalid grid rows")
        for c in row:
            if c not in ('.', '#', 'S'):
                raise ValueError("Invalid grid character")

    # Find starting position
