    for row_idx, row in enumerate(grid):
        if 'S' in row:
            if start is not None:
                raise ValueError("Multiple 'S' in grid")
            col_idx = row.index('S')
            start = (row_idx, col_idx)
    if start is None:
        raise ValueError("No 'S' in grid")
    row, col = start

    # Validate commands
    valid_commands = {'L', 'R', 'F'}
    for cmd in commands:
        if cmd not in valid_commands:
            raise ValueError("Invalid command character")

    # Directions: N=0, E=1, S=2, W=3
    direction = 0
    visited = set()
    visited.add((row, col))

    # Process each command
    for cmd in commands:
        if cmd == 'L':
            direction = (direction - 1) % 4
        elif cmd == 'R':
            direction = (direction + 1) % 4
        else:  # 'F'
            new_row, new_col = row, col
            if direction == 0:  # N
                new_row = row - 1
            elif direction == 1:  # E
                new_col = col + 1
            elif direction == 2:  # S
                new_row = row + 1
            else:  # W
