    else:  # direction is "down"
        for r in unique_requests:
            if r < start:
                current_group.append(r)
            else:
                opposite_group.append(r)

    # Sort current group based on direction
    if direction == "up":
        current_group.sort()
    else:
        current_group.sort(reverse=True)

    # Process current group
    current_position = start
    for floor in current_group:
        stops.append(floor)
        distance += abs(floor - current_position)
        current_position = floor

    # If no current group, no need to process opposite
