                L[i][j] = L[i+1][j+1] + 1
            else:
                L[i][j] = max(L[i+1][j], L[i][j+1])

    # Reconstruct the LCS
    i = j = 0
    r = L[i][j]
    result = []

    while r > 0:
        # Collect all possible characters present in both a[i:] and b[j:]
        chars_a = set(a[i:])
        chars_b = set(b[j:])
        common_chars = chars_a.intersection(chars_b)
        # Iterate through characters in sorted order
